"""Shared types and helpers for every SYNTHETIC evidence generator.

Each generator module exposes ``generate(story: Story, case_dir: Path) -> list[GeneratedFile]``.
The CLI merges the results into ``<case_dir>/manifest.json`` (what to upload) and
``<case_dir>/answer_key.json`` (which story facts live at which locator, for the eval gold set).
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Literal

SYNTHETIC_NOTICE = (
    "SYNTHETIC DATA - fictional case generated by CaseLens data_gen. "
    "No real people, places, vehicles, phone numbers, or events."
)

EvidenceType = Literal["pdf", "audio", "video", "csv"]


@dataclass(frozen=True)
class FactLocation:
    """Where one story fact (event / entity id from the story) appears in one evidence file.

    ``locator`` follows the answer-contract Locator shapes:
    pdf {kind, page, bbox?}, audio {kind, start_ms, end_ms, speaker?},
    video {kind, start_ms, end_ms?, frame_idx?, bbox?, track_id?}, record {kind, table, row_id}.
    """

    fact_id: str
    locator: dict[str, Any]
    note: str = ""


@dataclass
class GeneratedFile:
    path: Path
    evidence_type: EvidenceType
    description: str
    facts: list[FactLocation] = field(default_factory=list)
    recorded_at: str | None = None


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1 << 16), b""):
            digest.update(block)
    return digest.hexdigest()


def write_manifest(case_dir: Path, files: list[GeneratedFile]) -> None:
    """Write manifest.json and answer_key.json for one generated case."""
    manifest = {
        "notice": SYNTHETIC_NOTICE,
        "files": [
            {
                "path": f.path.relative_to(case_dir).as_posix(),
                "type": f.evidence_type,
                "description": f.description,
                "sha256": sha256_file(f.path),
                "recorded_at": f.recorded_at,
            }
            for f in sorted(files, key=lambda f: f.path.as_posix())
        ],
    }
    answer_key = {
        "notice": SYNTHETIC_NOTICE,
        "facts": [
            {"evidence": f.path.relative_to(case_dir).as_posix(), **asdict(fact)}
            for f in files
            for fact in f.facts
        ],
    }
    for name, payload in (("manifest.json", manifest), ("answer_key.json", answer_key)):
        (case_dir / name).write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
